export const catalogById = new Map(equipmentCatalog.map(entry => [entry.id, entry]));

export function getCatalogRecord(id) {
  return catalogById.get(id) || null;
}

export function getAvailableInventoryIds(entry, placedItems = []) {
  if (!entry) return [];
  const assigned = new Set(placedItems.map(i => i.inventoryId).filter(Boolean));
  return entry.inventoryIds.filter(id => !assigned.has(id));
}

export function findCatalogRecords({query='',sourcedOnly=false,availableOnly=false}={},placedItems=[]){
  const terms=query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  return equipmentCatalog.filter(entry=>{
    if(sourcedOnly&&!entry.dimensionsIn)return false;
    if(availableOnly&&!getAvailableInventoryIds(entry,placedItems).length)return false;
    const text=[entry.id,entry.area,entry.name,entry.manufacturer,entry.modelNumber,
      ...entry.inventoryIds,...entry.muscleGroups,...entry.exercises,...entry.capabilities].join(' ').toLowerCase();
    return terms.every(term=>text.includes(term));
  });
}

export function applyCatalogIdentity(item, entry, inventoryId = '') {
  if (!entry || !item || !['strength', 'free', 'cardio'].includes(item.category)) {
    throw new Error('Choose an equipment footprint and a valid catalog entry.');
  }
  if (inventoryId && !entry.inventoryIds.includes(inventoryId)) {
    throw new Error('The inventory ID does not belong to this model.');
  }
  return {
    ...item,
    name: entry.name,
    catalogId: entry.id,
    inventoryId,
    manufacturer: entry.manufacturer,
    modelNumber: entry.modelNumber || '',
    modelStatus: entry.modelStatus,
    muscleGroups: item.catalogId===entry.id&&Array.isArray(item.muscleGroups)?[...item.muscleGroups]:[...entry.muscleGroups],
    exercises: item.catalogId===entry.id&&Array.isArray(item.exercises)?[...item.exercises]:[...entry.exercises],
    capabilities: item.catalogId===entry.id&&Array.isArray(item.capabilities)?[...item.capabilities]:[...entry.capabilities],
    // Dimensions and coordinates remain untouched when linking an existing item.
  };
}
